insert into public.deployment_check (check_key, section, title, why, kind, severity, expected, status, value, detail, last_run_at, active, sort_order)
values
 ('sched.rooms_from_blueprint', '17 Scheduling & zones', 'Rooms come from the facility blueprint, as data', 'Owner 12 Sep: "use room from facility page". facility_room holds the 30 rooms of A1.1 exactly as facility.ts draws them (generated by tools/checks/facility-rooms-from-blueprint.mjs, not typed): 24 Metrc-mapped, geometry kept for the map, editable by sign-off roles. Lane: Claude (done); Grok repoints the facility page to read it (sched.facility_page_reads_table).', 'manual', 'GO', '30 rooms = facility.ts', 'PASS', '30 rooms / 24 Metrc / 29 staffable', 'Measured 12 Sep 2026 after migration claude_scheduling_01.', now(), true, 140),
 ('sched.one_zone_table', '17 Scheduling & zones', 'One zone table, seeded from the blueprint groups', 'Two tables defined a zone (zone, zones); every FK pointed at zones while the registry functions wrote zone. zones is now the one table, zone (0 rows) dropped, tg_add/rename/retire_zone and v_zone_board/v_zone_vocabulary_drift repointed. 16 zones mapped onto the 8 scheduling departments; every staffable room sits in exactly one zone. schedule_assignments (0 rows, no reader) dropped too. Lane: Claude (done).', 'manual', 'GO', '1 definition; every staffable room placed once', 'PASS', '16 zones / 29 rooms placed / 0 unplaced', 'v_zone_board now shows plants and pounds per zone from the Metrc room board: Flower Rooms 4,380 plants + Veg 30 = 4,410, the certified active-plant count.', now(), true, 141),
 ('sched.policy_in_settings', '17 Scheduling & zones', 'Every scheduling rule is a row in Settings, with history', 'Owner 12 Sep: policies, procedures and the shift model are edited on the back end in Settings/permissions. scheduling_policy (one row): sign-off roles {owner, executive, cfo, hr}, draft 14 d / post 7 d, rest 10 h, max 6 days in a row, nobody in training alone, primaries before floaters, overtime last, swap/claim sign-off, facility time zone, default shift. Every change lands in scheduling_policy_history with who/when/before/after. Call-out notice stays in attendance_policy (2 h). Lane: Claude (done); CFO/HR revise.', 'manual', 'GO', '1 policy row; revisions kept', 'PASS', 'signoff {owner,executive,cfo,hr}; 14/7 d; rest 10 h; 6 days', 'Claude''s recommended values, 12 Sep 2026 — owner: "enter what you recommend, CFO or HR to revise later".', now(), true, 142),
 ('sched.training_matrix', '17 Scheduling & zones', 'Training matrix: who may be placed where (in_training / trained / can_lead, re-cert dates)', 'employee_department_skill is the only table the drafter places people from. Floater = trained or in training in 2+ departments (owner ruling 12 Sep), derived in v_floaters, never a checkbox. Seeded ''trained'' from each primary department so drafting can start; HR verifies trained_on / trained_by and adds every other department a person is trained or training in. Lane: Claude (done); HR (verify).', 'manual', 'WATCH', 'every active employee has ≥1 verified row', 'WARN', '17 seeded / 0 verified / 0 floaters / 11 active with no department', 'Measured 12 Sep 2026. WARN until hr verifies the 17 and assigns the 11.', now(), true, 143),
 ('sched.shift_model', '17 Scheduling & zones', 'Shift templates and the two break waves', 'Day · Wave 1 and Day · Wave 2 (08:00–16:30, 30 min unpaid meal at 12:00 / 13:30) from the owner''s 10 Sep ruling on two waves; the 8 Aug company-wide window is retired. v_on_the_floor now picks ONE window per person (it fanned out) and reads the clock in the facility time zone (it read UTC). Start time 08:00 is a recommendation. Lane: Claude (done); HR revises.', 'manual', 'GO', '≥1 active template; 1 break window per person', 'PASS', '2 templates / 2 waves / 1 retired', 'Owner to confirm the 08:00 start (owner.sched_rulings).', now(), true, 144),
 ('sched.staffing_requirements', '17 Scheduling & zones', 'A headcount per zone per weekday exists (recommended, revisable)', 'zone_staffing_requirements seeded Mon–Fri from today''s ACTIVE primary headcount: Flower 3, Veg 1, Trim 2, Hydro 1, Solventless 1, Flower Packaging 2, Pre-Rolls 2, Economy Pre-Rolls 3, Dock 1 = 16; weekend Flower 1 (watering). Zones with no dedicated headcount today are 0 (Dry & Cure, Production Room, Frozen & Biomass, Grind, Supplies, Vaults, QA). Effective Mon 14 Sep. Lane: Claude (done); HR/CFO revise in Settings › Staffing.', 'manual', 'WATCH', 'every zone has a requirement HR has confirmed', 'WARN', '16 weekday heads / 2 weekend; 0 confirmed by HR', 'Recommendation, not a ruling.', now(), true, 145),
 ('sched.drafter_live_test', '17 Scheduling & zones', 'Push-button draft works end to end under the rules, and nothing reached staff', 'f_schedule_candidates ranks every employee for a zone/date/shift with blockers (not trained, licence, unavailable, time off, already scheduled, rest, days in a row) and warnings (overtime, in training, hours cap); f_draft_schedule fills every requirement from it with the reason on each cell and open shifts that say why nobody fit. Live test 14–20 Sep: 82 shifts placed, 0 open, 2 cells to review (weekend cover = overtime, flagged), nobody over 6 days, local times 08:00–16:30. Both test drafts discarded; nothing posted. Lane: Claude (done).', 'manual', 'GO', 'draft fills requirements; 0 rule breaches; 0 posted', 'PASS', '82 placed / 0 open / 2 OT cells / 0 posted', 'Whichever bot drafts later calls the same function, so a rule-breaking placement is impossible rather than caught.', now(), true, 146),
 ('sched.builder_could_not_save', '17 Scheduling & zones', 'Defect fixed: the Schedule Builder could never save a draft', 'schedule_drafts, schedule_draft_lines and zones had SELECT-only RLS policies, so "Save draft" on the builder page was refused for every signed-in role since the page shipped. Write policies for f_can_decide_hr() added. Also fixed: f_post_schedule cast the draft''s timestamptz into a time-of-day in UTC (08:00 ET would have posted as 12:00) — it now converts in the facility time zone. Lane: Claude (done).', 'manual', 'GO', 'sign-off roles can write; posted times are local', 'PASS', '3 tables writable; tz conversion live', 'Found and fixed 12 Sep 2026 while building the foundation.', now(), true, 147),
 ('sched.settings_pages', '17 Scheduling & zones', 'Settings pages: rooms, zones, staffing, shift model, policy, training & onboarding', 'Owner 12 Sep: users build room details, modify staffing, departments, zones, rooms, shift model, call-out/swap policies and procedures, training and onboarding — all in Settings/permissions. The tables and their write policies exist; the pages do not. Lane: Grok / HR module (TG-05), after Bots.', 'manual', 'NO-GO', 'each table editable from Settings by sign-off roles', 'PENDING', null, 'Tables ready: facility_room, zones, zone_staffing_requirements, shift_templates, break_windows, scheduling_policy, employee_department_skill, lifecycle_steps.', null, true, 148),
 ('sched.builder_grid', '17 Scheduling & zones', 'Schedule Builder to the standard of the popular scheduling apps', 'Week grid (people × days, zone colour per cell), drag/copy, Copy last week, Apply template, availability and time-off shaded under the cell, live per-person hours/OT/cost footer, per-zone required-vs-filled bar, Draft week / 2 weeks / month button (calls f_draft_schedule), cell reasons and conflicts shown, Post to staff. The facility-map view of zones with plants/packages beside people is the one thing no scheduling site can do. Lane: Grok / HR module.', 'manual', 'NO-GO', 'grid + push-button draft + post', 'PENDING', null, 'Data side complete: v_schedule_draft_review, f_schedule_candidates, f_draft_schedule, f_post_schedule.', null, true, 149),
 ('sched.callout_cover', '17 Scheduling & zones', 'Call-outs, swaps and open shifts with a "who is available" list', 'f_cover_candidates(open_shift) returns the ranked list (skill, hours to OT, availability, reasons). Pages: file a call-out → cell becomes an open shift → manager taps a cover or opens it to claims; swaps need both sides and sign-off per policy. Lane: Claude (function done); Grok / HR (pages).', 'manual', 'WATCH', 'call-out → open shift → cover in 3 taps', 'PENDING', null, null, null, true, 150),
 ('sched.facility_page_reads_table', '17 Scheduling & zones', 'The facility map reads facility_room, not the static file', 'Until then there are two definitions of a room (facility.ts and facility_room). tools/tests/facility-rooms-match-blueprint.test.mjs holds them equal in the repo; the page repoint closes the gap. Lane: Grok.', 'manual', 'WATCH', '1 definition of a room', 'PENDING', null, null, null, true, 151),
 ('sched.harvest_driven_requirements', '17 Scheduling & zones', 'Trim, dry and packaging headcount driven by the harvest calendar and production runs', 'zone_staffing_requirements.driver supports harvest / production; today every row is manual. A takedown should raise Dry & Cure and Trim for its days automatically; a production run should raise Production Room. Lane: Claude.', 'manual', 'WATCH', 'requirements move with the harvest calendar', 'PENDING', null, null, null, true, 152),
 ('sched.notify_on_post', '17 Scheduling & zones', 'Posting a schedule notifies the people on it', 'Through alert_outbox to recipients the owner configures in the app — never hardwired (owner rule 12 Sep). Lane: Claude.', 'manual', 'WATCH', 'post → notification per person', 'PENDING', null, null, null, true, 153),
 ('sched.onboarding_tracking', '17 Scheduling & zones', 'Onboarding progress is tracked per person', 'lifecycle_steps has 21 steps (phase, owner role, due offset, legal, blocks start); lifecycle_progress has 0 rows and hr_documents 0 — nobody has been onboarded through the OS yet. Training records now live in employee_department_skill. Lane: HR (data); Grok (page).', 'manual', 'WATCH', 'every active employee has lifecycle rows', 'WARN', '0 of 27 active have lifecycle rows', 'Measured 12 Sep 2026.', now(), true, 154),
 ('owner.sched_rulings', '17 Scheduling & zones', 'Owner confirms the recommended scheduling values', 'To confirm or change: shift start 08:00 (both waves); Production Room and Grind mapped to Extraction / Packaging per the blueprint; Cheap Pre-Rolls as its own zone in the pre-roll room; weekend flower cover 1 head (it is overtime for everyone at 40 h — hire, part-time, or accept OT); the 11 active employees with no department. Ruled 12 Sep: floater = trained or in training in 2+ departments; sign-off = CEO, CFO, HR; skill levels in_training / trained / can_lead with re-cert dates.', 'owner', 'OWNER', 'confirmed or changed in Settings', 'PENDING', null, null, null, true, 155)
